#include <bits/stdc++.h>
using namespace std;
struct Basis {int R,W,rank=0; vector<uint64_t*> piv; vector<unique_ptr<uint64_t[]>> store; Basis(int r):R(r),W((r+63)/64),piv(r,nullptr){store.reserve(6000);} bool add(vector<uint64_t>&x){while(1){int wi=0;while(wi<W&&x[wi]==0)wi++;if(wi==W)return false;int bit=__builtin_ctzll(x[wi]);int p=(wi<<6)+bit;auto b=piv[p];if(!b){auto m=make_unique<uint64_t[]>(W);memcpy(m.get(),x.data(),W*8);piv[p]=m.get();store.push_back(move(m));rank++;return true;}for(int j=wi;j<W;j++)x[j]^=b[j];}}};
void col(const array<int,8>&p,vector<uint64_t>&x){fill(x.begin(),x.end(),0);for(int path=0;path<512;path++){unsigned as=0;for(int k=0;k<8;k++){int e=(((path>>k)&1)<<1)|((path>>(k+1))&1);as|=(unsigned)e<<(2*p[k]);}int out=((path&1)<<1)|((path>>8)&1);unsigned row=(as<<2)|out;x[row>>6]^=1ULL<<(row&63);}}
int main(){int R=262144,W=4096;Basis G(R);vector<uint64_t>x(W);for(int last=7;last>=0;--last){vector<int>r;for(int i=0;i<8;i++)if(i!=last)r.push_back(i);Basis L(R);do{array<int,8>p;for(int i=0;i<7;i++)p[i]=r[i];p[7]=last;col(p,x);L.add(x);}while(next_permutation(r.begin(),r.end()));cerr<<"chunk "<<last<<" local "<<L.rank<<"\n";for(auto &u:L.store){memcpy(x.data(),u.get(),W*8);G.add(x);}cerr<<"global "<<G.rank<<"\n";}cout<<"rank "<<G.rank<<" kernel "<<40320-G.rank<<"\n";}
